import{_ as n,C as d,o as u,c,a2 as p,E as t,w as a,a as o}from"./chunks/framework.CZcFxxdw.js";const v=JSON.parse('{"title":"future、任务与线程池","description":"从 std::async 到 promise/packaged_task，构建灵活的异步任务通道与线程池基础设施","frontmatter":{"title":"future、任务与线程池","description":"从 std::async 到 promise/packaged_task，构建灵活的异步任务通道与线程池基础设施"},"headers":[],"relativePath":"vol5-concurrency/ch05-future-task-threadpool/index.md","filePath":"vol5-concurrency/ch05-future-task-threadpool/index.md","lastUpdated":null}'),i={name:"vol5-concurrency/ch05-future-task-threadpool/index.md"};function l(f,e,_,h,k,m){const r=d("ChapterLink"),s=d("ChapterNav");return u(),c("div",null,[e[4]||(e[4]=p('<h1 id="future、任务与线程池" tabindex="-1">future、任务与线程池 <a class="header-anchor" href="#future、任务与线程池" aria-label="Permalink to &quot;future、任务与线程池&quot;">​</a></h1><p>前几章我们一直在跟底层原语打交道：thread、mutex、atomic、condition variable。这些东西给了我们精确的控制力，但也带来了大量的手动管理负担——你需要自己设计同步机制、自己传递结果、自己处理错误。C++ 标准库提供了一套更高层的异步抽象来简化这些工作：future 是结果容器，promise 是值的写端，packaged_task 是任务的封装器，async 是最便捷的启动方式。它们组合在一起，构成了线程池和任务队列的基础设施。</p><p>这一章我们从 <code>std::async</code> 和 <code>std::future</code> 开始，理解异步任务的启动策略和结果获取机制；然后深入 <code>std::promise</code> 和 <code>std::packaged_task</code>，学会手动控制值的设置和任务的执行；最后我们会讨论 <code>std::shared_future</code> 和线程池的设计模式，把前面学到的所有组件串联起来。</p><h2 id="本章内容" tabindex="-1">本章内容 <a class="header-anchor" href="#本章内容" aria-label="Permalink to &quot;本章内容&quot;">​</a></h2>',4)),t(s,{variant:"sub"},{default:a(()=>[t(r,{href:"01-std-async-and-future"},{default:a(()=>[...e[0]||(e[0]=[o("std::async 与 future",-1)])]),_:1}),t(r,{href:"02-promise-and-packaged-task"},{default:a(()=>[...e[1]||(e[1]=[o("promise 与 packaged_task",-1)])]),_:1}),t(r,{href:"03-jthread-and-stop-token"},{default:a(()=>[...e[2]||(e[2]=[o("jthread 与停止令牌",-1)])]),_:1}),t(r,{href:"04-thread-pool"},{default:a(()=>[...e[3]||(e[3]=[o("线程池设计",-1)])]),_:1})]),_:1})])}const C=n(i,[["render",l]]);export{v as __pageData,C as default};
